    rng = np.random.default_rng(seed)
    n = 20
    X0 = rng.normal(loc=[0.2, 0.1, 0.1, 0.05], scale=0.05, size=(n // 2, 4))
    X1 = rng.normal(loc=[0.6, 0.4, 0.5, 0.2], scale=0.05, size=(n // 2, 4))
