import pennylane as qml
import numpy as np

def ghz_statevector(n):
    """Amplitudes of the n-qubit GHZ state via PennyLane."""
    dev = qml.device('default.qubit', wires=n)
    @qml.qnode(dev)
    def circuit():
        qml.Hadamard(0)
        for i in range(1, n):
            qml.CNOT([0, i])
        return qml.state()
    return circuit()

