def rx_expectation(theta):
    """<Z> after RX(theta) on |0> via PennyLane."""
    dev = qml.device('default.qubit', wires=1)
    @qml.qnode(dev)
    def circuit(t):
        qml.RX(t, wires=0)
        return qml.expval(qml.Z(0))
    return float(circuit(theta))

