def maxcut_cost(bitstring, edges):
    bits = [int(c) for c in bitstring]
    c = 0
    for u, v in edges:
        if bits[u] != bits[v]:
            c += 1
    return c

def brute_force_maxcut(n_nodes, edges):
    best = None
    for i in range(1 << n_nodes):
        bs = format(i, '0' + str(n_nodes) + 'b')
        c = maxcut_cost(bs, edges)
        if best is None or c > best[1] or (c == best[1] and bs < best[0]):
            best = (bs, c)
    return best

def qaoa_cost_landscape(n_nodes, edges):
    res = []
    for i in range(1 << n_nodes):
        bs = format(i, '0' + str(n_nodes) + 'b')
        res.append((bs, maxcut_cost(bs, edges)))
    res.sort(key=lambda x: (-x[1], x[0]))
    return res

