import numpy as np

def depolarizing(rho, p):
    """Apply a depolarizing channel: rho -> (1-p)rho + p I/d."""
    d = rho.shape[0]
    I = np.eye(d, dtype=complex)
    return (1 - p) * rho + p * (I / d)

