def von_neumann_entropy(rho):
    """Entropy: -Tr(rho log2 rho)."""
    w = np.linalg.eigvalsh(rho)
    w = w[w > 1e-12]
    if w.size == 0:
        return 0.0
    return float(-np.sum(w * np.log2(w)))

