def partial_trace(rho, dA, dB):
    """Partial trace over the second (B) subsystem."""
    out = np.zeros((dA, dA), dtype=complex)
    for i in range(dA):
        for j in range(dA):
            s = 0j
            for b in range(dB):
                s += rho[i * dB + b, j * dB + b]
            out[i, j] = s
    return out

