import numpy as np

def stabilizer_generators():
    return ['XZZXI', 'IXZZX', 'XIXZZ', 'ZXIXZ']

def _pauli_to_vec(p):
    table = {'I': (0, 0), 'X': (1, 0), 'Y': (1, 1), 'Z': (0, 1)}
    return np.array(table[p], dtype=int)

def stabilizer_matrix():
    rows = []
    for g in stabilizer_generators():
        sx, sz = [], []
        for ch in g:
            x, z = _pauli_to_vec(ch)
            sx.append(x); sz.append(z)
        rows.append(sx + sz)
    return np.array(rows, dtype=int)

def syndrome_of(error):
    if len(error) != 5 or any(c not in 'IXYZ' for c in error):
        raise ValueError('error must be a length-5 Pauli string')
    ex = np.array([_pauli_to_vec(c)[0] for c in error], dtype=int)
    ez = np.array([_pauli_to_vec(c)[1] for c in error], dtype=int)
    S = stabilizer_matrix()
    Sx = S[:, :5]; Sz = S[:, 5:]
    syndrome = (Sx @ ez + Sz @ ex) % 2
    return ''.join(str(b) for b in syndrome)

def single_qubit_error_table():
    table = {'I': '0000'}
    for q in range(5):
        for p in 'XYZ':
            err = ['I'] * 5
            err[q] = p
            table[p + str(q)] = syndrome_of(''.join(err))
    return table

