def qaoa_phase_objective(bitstring, edges, gamma):
    """Cut edges add cos(gamma), uncut add sin(gamma)."""
    bits = [int(c) for c in bitstring]
    total = 0.0
    for u, v in edges:
        if bits[u] != bits[v]:
            total += np.cos(gamma)
        else:
            total += np.sin(gamma)
    return float(total)

