def bitstring_entropy(bitstring):
    """Shannon entropy of the 0/1 histogram of a bitstring."""
    n = len(bitstring)
    p1 = bitstring.count('1') / n
    if p1 == 0 or p1 == 1:
        return 0.0
    return -p1 * math.log2(p1) - (1 - p1) * math.log2(1 - p1)

