"""Bell-state construction (v19 gap drill)."""
import math


def _hadamard_q0(state):
    out = [0j] * 4
    for i in range(4):
        j = i ^ 2
        if (i >> 1) & 1:
            out[i] = (state[j] - state[i]) / math.sqrt(2)
        else:
            out[i] = (state[i] + state[j]) / math.sqrt(2)
    return out


def _cnot_q0_q1(state):
    out = list(state)
    for i in range(4):
        if (i >> 1) & 1:
            out[i] = state[i ^ 1]
    return out


def bell_circuit(which="phi_plus"):
    """Return the 4-amplitude statevector of a named Bell state."""
    sv = _cnot_q0_q1(_hadamard_q0([1 + 0j, 0j, 0j, 0j]))
    if which == "phi_plus":
        return sv
    if which == "phi_minus":
        return [sv[0], sv[1], -sv[2], -sv[3]]
    if which == "psi_plus":
        return [sv[1], sv[0], sv[3], sv[2]]
    if which == "psi_minus":
        return [sv[1], sv[0], -sv[3], -sv[2]]
    raise ValueError("unknown bell state: " + which)


def parity_check(bits):
    """Return 1 if the bitstring has odd parity, else 0."""
    return sum(1 for c in bits if c == "1") % 2


def sample_bell_state(which="phi_plus", shots=8, seed=7):
    """Sample measurement outcomes of a Bell state. Returns {bitstring: count}."""
    import random
    rng = random.Random(seed)
    probs = [abs(a) ** 2 for a in bell_circuit(which)]
    labels = ["00", "01", "10", "11"]
    counts = {}
    for _ in range(shots):
        x = rng.random()
        acc = 0.0
        for lab, p in zip(labels, probs):
            acc += p
            if x < acc:
                counts[lab] = counts.get(lab, 0) + 1
                break
        else:
            counts[labels[-1]] = counts.get(labels[-1], 0) + 1
    return counts

"""Density matrix utilities (v19 gap drill)."""
import math


def tensor_product(a, b):
    """Kronecker product of two matrices."""
    ra, ca = len(a), len(a[0])
    rb, cb = len(b), len(b[0])
    out = [[0.0] * (ca * cb) for _ in range(ra * rb)]
    for i in range(ra):
        for j in range(ca):
            for k in range(rb):
                for l in range(cb):
                    out[i * rb + k][j * cb + l] = a[i][j] * b[k][l]
    return out


def density_from_state(state):
    """Density matrix |psi><psi| from a statevector (list)."""
    n = len(state)
    return [[state[i] * state[j].conjugate() for j in range(n)] for i in range(n)]


def partial_trace(rho, keep, n_qubits):
    """Partial trace over the qubits not in `keep` (0-indexed, q0 = MSB)."""
    dim = 2 ** n_qubits
    keep = sorted(keep)
    kdim = 2 ** len(keep)
    out = [[0.0] * kdim for _ in range(kdim)]
    for i in range(dim):
        for j in range(dim):
            # decompose indices
            same = True
            for q in range(n_qubits):
                if q in keep:
                    continue
                if ((i >> (n_qubits - 1 - q)) & 1) != ((j >> (n_qubits - 1 - q)) & 1):
                    same = False
                    break
            if not same:
                continue
            # map kept bits
            ki = 0
            kj = 0
            for pos, q in enumerate(keep):
                ki |= ((i >> (n_qubits - 1 - q)) & 1) << (len(keep) - 1 - pos)
                kj |= ((j >> (n_qubits - 1 - q)) & 1) << (len(keep) - 1 - pos)
            out[ki][kj] += rho[i][j]
    return out


def purity(rho):
    """Tr(rho^2)."""
    n = len(rho)
    return sum(rho[i][j] * rho[j][i] for i in range(n) for j in range(n)).real

"""Quantum channel drills (v19 gap drill)."""
import math


def depolarizing_channel(rho, p):
    """Apply depolarizing channel: rho -> (1-p) rho + p I/2 (single qubit)."""
    ident = [[1.0, 0.0], [0.0, 1.0]]
    return [[(1 - p) * rho[r][c] + (p / 2) * ident[r][c] for c in range(2)]
            for r in range(2)]


def amplitude_damping_channel(rho, gamma):
    """Apply amplitude damping to a single-qubit density matrix."""
    k0 = [[1.0, 0.0], [0.0, math.sqrt(1 - gamma)]]
    k1 = [[0.0, math.sqrt(gamma)], [0.0, 0.0]]
    out = [[0.0] * 2 for _ in range(2)]
    for k in (k0, k1):
        for r in range(2):
            for c in range(2):
                s = 0.0
                for i in range(2):
                    for j in range(2):
                        s += k[r][i] * rho[i][j] * k[c][j]
                out[r][c] += s
    return out


def channel_fidelity(rho, sigma):
    """Uhlmann fidelity squared for 2x2 density matrices."""
    # F = (Tr sqrt(sqrt(rho) sigma sqrt(rho)))^2; for commuting cases use simpler form
    import cmath
    # generic 2x2 via eigen-free formula: F = Tr(rho sigma) + 2 sqrt(det(rho) det(sigma))
    tr = sum(rho[r][r] * sigma[r][r] + rho[r][1 - r] * sigma[1 - r][r] for r in range(2))
    def det(m):
        return m[0][0] * m[1][1] - m[0][1] * m[1][0]
    val = tr + 2 * math.sqrt(max(0.0, det(rho) * det(sigma)))
    return min(1.0, max(0.0, val.real if isinstance(val, complex) else val))

"""MaxCut utilities on grid graphs (v19 gap drill)."""
import itertools


def maxcut_cost(bitstring, edges):
    """MaxCut cost: edges crossing the partition."""
    return sum(1 for u, v in edges if bitstring[u] != bitstring[v])


def brute_force_maxcut(n_nodes, edges):
    """Exhaustive best (bitstring, cost); ties -> lexicographically smallest."""
    best_b, best_c = None, -1
    for bits in itertools.product("01", repeat=n_nodes):
        c = maxcut_cost(bits, edges)
        if c > best_c or (c == best_c and (best_b is None or "".join(bits) < best_b)):
            best_b, best_c = "".join(bits), c
    return best_b, best_c


def qaoa_cost_landscape(n_nodes, edges):
    """All (bitstring, cost), sorted by cost desc then bitstring asc."""
    rows = [("".join(bits), maxcut_cost(bits, edges))
            for bits in itertools.product("01", repeat=n_nodes)]
    rows.sort(key=lambda t: (-t[1], t[0]))
    return rows

def _normalize_pauli(label: str) -> str:
    normalized = label.strip().upper()
    if normalized not in {"I", "X", "Y", "Z"}:
        raise ValueError(f"unsupported Pauli operator: {label!r}")
    return normalized


_CONJUGATION_RULES = {
    "H": {
        "I": (1, "I"),
        "X": (1, "Z"),
        "Y": (-1, "Y"),
        "Z": (1, "X"),
    },
    "S": {
        "I": (1, "I"),
        "X": (1, "Y"),
        "Y": (-1, "X"),
        "Z": (1, "Z"),
    },
    "SDG": {
        "I": (1, "I"),
        "X": (-1, "Y"),
        "Y": (1, "X"),
        "Z": (1, "Z"),
    },
}


def apply_gate_sequence(pauli: str, gates: list[str]) -> tuple[int, str]:
    """Update a signed single-qubit Pauli under Clifford conjugation."""
    raw = pauli.strip()
    sign = -1 if raw.startswith("-") else 1
    label = raw[1:] if raw.startswith("-") else raw
    label = _normalize_pauli(label)

    for gate in gates:
        gate_name = gate.strip().upper()
        if gate_name not in _CONJUGATION_RULES:
            raise ValueError(f"unsupported gate: {gate!r}")
        gate_sign, next_label = _CONJUGATION_RULES[gate_name][label]
        sign *= gate_sign
        label = next_label

    return sign, label

import cmath


def qft_basis_state(n_qubits: int, basis_index: int) -> list[complex]:
    """Return the exact QFT statevector for computational basis |basis_index>."""
    if n_qubits <= 0:
        raise ValueError("n_qubits must be positive")
    dimension = 1 << n_qubits
    if not 0 <= basis_index < dimension:
        raise ValueError("basis_index out of range")

    scale = dimension ** -0.5
    return [
        scale * cmath.exp(2j * cmath.pi * basis_index * output_index / dimension)
        for output_index in range(dimension)
    ]

def controlled_phase_angle(k: int, n: int) -> float:
    """Return the phase angle 2*pi / 2^k applied by a controlled-phase
    rotation CP(2*pi/2^k) used in quantum adder circuits.

    Here k >= 1 indexes the rotation strength; for k=1 the rotation is
    a controlled-Z (pi phase) up to convention; we use 2*pi/2^k.
    """
    if k < 1 or k > n:
        raise ValueError("k must be in 1..n")
    if n < 1:
        raise ValueError("n must be positive")
    import math

    return 2.0 * math.pi / (1 << k)


def qft_adder_phase_schedule(n: int) -> list[list[float]]:
    """Return the n x n lower-triangular phase schedule for a QFT-based adder.

    schedule[i][j] (for j <= i) is the phase applied between control qubit i
    and target qubit j; schedule[i][j] = 0 for j > i. The diagonal entries
    represent single-qubit phase rotations; off-diagonal entries are
    controlled-phase angles.
    """
    if n < 1:
        raise ValueError("n must be positive")
    import math

    schedule = [[0.0] * n for _ in range(n)]
    for i in range(n):
        for j in range(i + 1):
            # Distance k = i - j + 1 (rotation strength)
            k = i - j + 1
            schedule[i][j] = 2.0 * math.pi / (1 << k)
    return schedule


def phase_kickback_sum(a: int, b: int, n: int) -> int:
    """Classically emulate the QFT-based modular adder on n qubits.

    Given two n-bit integers a and b in [0, 2^n), return (a + b) mod 2^n,
    which is what the quantum adder computes on the QFT-encoded target
    register after the phase-kickback controlled rotations.
    """
    if n < 1:
        raise ValueError("n must be positive")
    if not (0 <= a < (1 << n)) or not (0 <= b < (1 << n)):
        raise ValueError("a and b must be in [0, 2^n)")
    return (a + b) % (1 << n)

def phase_estimation(phase: float, n_bits: int) -> int:
    if n_bits <= 0:
        raise ValueError("n_bits must be positive")
    if not (0.0 <= phase < 1.0):
        raise ValueError("phase must be in [0, 1)")
    scale = 1 << n_bits
    return int(round(phase * scale)) % scale


def phase_from_measurement(measurement: int, n_bits: int) -> float:
    if n_bits <= 0:
        raise ValueError("n_bits must be positive")
    scale = 1 << n_bits
    if not (0 <= measurement < scale):
        raise ValueError("measurement out of range")
    return measurement / scale

def solve_simon_system(equations: list[tuple[int, int]], n: int) -> int:
    """Solve the linear system (over GF(2)) gathered by Simon's algorithm.

    Each equation is (y, b) where y is an n-bit integer measurement outcome
    and b = (y . s) mod 2 is guaranteed to be 0 for the unknown period string s.

    Find the unique non-zero s in {0,1}^n (returned as an integer) consistent
    with all equations y . s = 0. If only the trivial solution s = 0 is
    consistent, return 0. Raises ValueError if the system is inconsistent.
    """
    if n <= 0:
        raise ValueError("n must be positive")
    # Build augmented rows: bits of y followed by the RHS bit b
    rows = []
    for y, b in equations:
        row = [(y >> i) & 1 for i in range(n)] + [b & 1]
        rows.append(row)

    # Gaussian elimination over GF(2)
    pivot_row = 0
    pivots = []
    for col in range(n):
        # Find a row at or below pivot_row with a 1 in this column
        sel = None
        for r in range(pivot_row, len(rows)):
            if rows[r][col] == 1:
                sel = r
                break
        if sel is None:
            continue
        rows[pivot_row], rows[sel] = rows[sel], rows[pivot_row]
        for r in range(len(rows)):
            if r != pivot_row and rows[r][col] == 1:
                rows[r] = [(a ^ b) for a, b in zip(rows[r], rows[pivot_row])]
        pivots.append(col)
        pivot_row += 1
        if pivot_row == len(rows):
            break

    # Check for inconsistency: a row with all-zero coefficients but RHS=1
    for row in rows:
        if all(v == 0 for v in row[:n]) and row[n] == 1:
            raise ValueError("inconsistent system")

    # Determine if the only solution is s = 0 (full rank n)
    if len(pivots) == n:
        return 0

    # Free variable exists; pick the lowest-index free variable = 1
    free_vars = [c for c in range(n) if c not in pivots]
    if not free_vars:
        return 0
    s = [0] * n
    s[free_vars[0]] = 1
    # Back-substitute to determine pivot variables in terms of the free var
    for pr, pc in enumerate(pivots):
        val = rows[pr][n]
        for c in range(n):
            if c != pc and rows[pr][c] == 1 and s[c] == 1:
                val ^= 1
        s[pc] = val
    return sum(bit << i for i, bit in enumerate(s))

def rb_average_gate_fidelity(alpha: float, dim: int = 2) -> float:
    """Compute the average gate fidelity from the RB decay parameter alpha.

    For a d-dimensional system, the average gate fidelity of the noise
    channel is
        F_avg = alpha + (1 - alpha) / d

    where alpha is the depolarizing parameter (per Clifford) extracted
    from the RB decay curve F(m) = A * alpha^m + B.
    """
    if not 0.0 <= alpha <= 1.0:
        raise ValueError("alpha must be in [0, 1]")
    if dim < 2:
        raise ValueError("dim must be >= 2")
    return alpha + (1.0 - alpha) / dim


def rb_decay_parameter(f_avg: float, dim: int = 2) -> float:
    """Inverse of rb_average_gate_fidelity: given F_avg and d, return alpha."""
    if not (1.0 / dim) <= f_avg <= 1.0:
        raise ValueError(f"f_avg must be in [1/d, 1] = [1/{dim}, 1]")
    if dim < 2:
        raise ValueError("dim must be >= 2")
    return (f_avg - 1.0 / dim) / (1.0 - 1.0 / dim)


def rb_survival_probability(alpha: float, m: int, A: float = 1.0, B: float = 0.0) -> float:
    """Return the RB survival probability after m Cliffords:
    F(m) = A * alpha^m + B
    """
    if not 0.0 <= alpha <= 1.0:
        raise ValueError("alpha must be in [0, 1]")
    if m < 0:
        raise ValueError("m must be non-negative")
    return A * (alpha**m) + B

_BITS_TO_LABEL = {
    "00": "I",
    "01": "X",
    "10": "Z",
    "11": "XZ",
}

_LABEL_TO_BITS = {value: key for key, value in _BITS_TO_LABEL.items()}


def canonicalize_pauli_label(label: str) -> str:
    normalized = "".join(str(label).strip().upper().split())
    if normalized == "ZX":
        normalized = "XZ"
    if normalized not in _LABEL_TO_BITS:
        raise ValueError("unknown Pauli label")
    return normalized


def bits_to_pauli_label(bits: str) -> str:
    if bits not in _BITS_TO_LABEL:
        raise ValueError("bits must be one of 00, 01, 10, 11")
    return _BITS_TO_LABEL[bits]


def pauli_label_to_bits(label: str) -> str:
    return _LABEL_TO_BITS[canonicalize_pauli_label(label)]

"""GHZ state builder and Mermin (MABK) witness with an exact required API.

M = XXX - XYY - YXY - YYX; local hidden variable theories satisfy
|<M>| <= 2 while the GHZ state reaches 4. This task grades the
entry-point contract itself: every required function must exist under
its exact name.
"""

from __future__ import annotations

import numpy as np


def _pauli(name):
    if name == "X":
        return np.array([[0.0, 1.0], [1.0, 0.0]], dtype=complex)
    if name == "Y":
        return np.array([[0.0, -1.0j], [1.0j, 0.0]], dtype=complex)
    return np.eye(2, dtype=complex)


def _kron3(a, b, c):
    return np.kron(np.kron(a, b), c)


def ghz_state():
    """(|000> + |111>) / sqrt(2) as a length-8 state vector."""
    psi = np.zeros(8, dtype=complex)
    psi[0] = 1.0 / np.sqrt(2.0)
    psi[7] = 1.0 / np.sqrt(2.0)
    return psi


def mermin_operator():
    """M = XXX - XYY - YXY - YYX as an 8x8 matrix."""
    M = np.zeros((8, 8), dtype=complex)
    M += _kron3(_pauli("X"), _pauli("X"), _pauli("X"))
    for term in ("XYY", "YXY", "YYX"):
        M -= _kron3(_pauli(term[0]), _pauli(term[1]), _pauli(term[2]))
    return M


def expectation(psi, M):
    """Real part of psi^dagger M psi."""
    return float(np.real(np.conj(psi) @ M @ psi))


def witness_value(psi):
    """|<M>| minus the LHV bound of 2."""
    M = mermin_operator()
    return abs(expectation(psi, M)) - 2.0


def density_matrix(psi):
    """|psi><psi|."""
    return np.outer(psi, np.conj(psi))


def run_checks():
    """All witness quantities for the harness."""
    psi = ghz_state()
    M = mermin_operator()
    rho = density_matrix(psi)
    pur = float(np.sum(np.linalg.eigvalsh((rho + rho.conj().T) / 2.0) ** 2))
    return dict(
        m_exp=expectation(psi, M),
        witness=witness_value(psi),
        is_pure=pur,
    )


def main():
    res = run_checks()
    for key, value in res.items():
        print(key, "=", value)
    assert abs(abs(res["m_exp"]) - 4.0) < 1e-9, "GHZ must saturate |<M>| = 4"
    assert abs(res["witness"] - 2.0) < 1e-9, "witness must exceed the LHV bound by 2"
    assert abs(res["is_pure"] - 1.0) < 1e-12, "GHZ density matrix must be pure"
    print("GHZ Mermin witness OK")


if __name__ == "__main__":
    main()

"""Bitstring-to-phase register roundtrip with an exact required API.

phase = sum b_k / 2^k over the bit string (binary fraction 0.b1b2...bn).
This task grades the entry-point contract itself: every required function
must exist under its exact name.
"""

from __future__ import annotations

from fractions import Fraction


def bits_to_phase(bits):
    """Binary fraction 0.b1b2...bn as a float in [0, 1)."""
    return float(
        Fraction(bits, 2) if False else sum(int(b) / (2 ** (k + 1)) for k, b in enumerate(bits))
    )


def phase_to_bits(phase, n):
    """Nearest n-bit binary fraction (grid spacing 2^-n)."""
    scaled = phase * (2**n)
    nearest = int(round(scaled))
    if nearest >= 2**n:
        nearest = 2**n - 1
    return format(nearest, "0%db" % n)


def phase_grid(n):
    """Sorted list of the 2^n representable phases."""
    return [k / (2**n) for k in range(2**n)]


def roundtrip_error(bits):
    """|decode(encode(bits)) - bits| as phases; exact 0 on the grid."""
    phase = bits_to_phase(bits)
    back = phase_to_bits(phase, len(bits))
    return abs(bits_to_phase(back) - phase)


def register_diag(n):
    """Roundtrip diagnostics for an n-bit register."""
    errors = [roundtrip_error(format(k, "0%db" % n)) for k in range(2**n)]
    return dict(
        n_bits=n,
        n_phases=2**n,
        spacing=1.0 / (2**n),
        max_roundtrip_error=max(errors),
    )


def main():
    diag = register_diag(6)
    for key, value in diag.items():
        print(key, "=", value)
    assert bits_to_phase("101") == 0.625
    assert phase_to_bits(0.625, 3) == "101"
    assert diag["max_roundtrip_error"] == 0.0, "all grid points must roundtrip exactly"
    print("phase register roundtrip OK")


if __name__ == "__main__":
    main()

"""Combined drill: gate alias normalization + phase-register roundtrip.

Graded entry points: normalize_gate_sequence, phase_to_register_bits,
register_bits_to_phase - all three under exact holdout names."""

from __future__ import annotations

_ALIASES = dict(h="H", hadamard="H", x="X", pauli_x="X", cx="CX", cnot="CX")


def normalize_gate_sequence(gates):
    normalized = []
    for gate in gates:
        key = gate.strip().lower()
        canonical = _ALIASES.get(key)
        if canonical is None:
            raise ValueError("unknown gate: %s" % gate)
        normalized.append(canonical)
    return normalized


def phase_to_register_bits(phase, n_qubits):
    if n_qubits <= 0:
        raise ValueError("n_qubits must be positive")
    if not (0.0 <= phase < 1.0):
        raise ValueError("phase must be in [0, 1)")
    scale = 1 << n_qubits
    integer_rep = int(phase * scale)
    return [(integer_rep >> shift) & 1 for shift in range(n_qubits - 1, -1, -1)]


def register_bits_to_phase(bits):
    if not bits:
        raise ValueError("bits list cannot be empty")
    if any(bit not in (0, 1) for bit in bits):
        raise ValueError("bits must be 0 or 1")
    integer_rep = 0
    for bit in bits:
        integer_rep = (integer_rep << 1) | bit
    return integer_rep / (1 << len(bits))

"""Depolarizing + amplitude-damping channel suite - exact holdout API.

Graded entry points: depolarizing_channel, amplitude_damping_channel,
channel_fidelity. Dense 2x2 lists, numpy-free reference."""

from __future__ import annotations

import math


def _mat_scale(c, m):
    return [[c * m[0][0], c * m[0][1]], [c * m[1][0], c * m[1][1]]]


def _mat_add(a, b):
    return [[a[0][0] + b[0][0], a[0][1] + b[0][1]], [a[1][0] + b[1][0], a[1][1] + b[1][1]]]


def _mat_mul(a, b):
    return [[sum(a[i][k] * b[k][j] for k in range(2)) for j in range(2)] for i in range(2)]


def _dagger(m):
    return [[m[j][i].conjugate() for j in range(2)] for i in range(2)]


def depolarizing_channel(rho, p):
    identity_half = [[0.5, 0.0], [0.0, 0.5]]
    return _mat_add(_mat_scale(1 - p, rho), _mat_scale(p, identity_half))


def amplitude_damping_channel(rho, gamma):
    sg = math.sqrt(gamma)
    s1g = math.sqrt(1 - gamma)
    K0 = [[1, 0], [0, s1g]]
    K1 = [[0, sg], [0, 0]]
    out = _mat_add(
        _mat_mul(_mat_mul(K0, rho), _dagger(K0)), _mat_mul(_mat_mul(K1, rho), _dagger(K1))
    )
    return [[v.real if isinstance(v, complex) else v for v in row] for row in out]


def channel_fidelity(rho, sigma):
    tr_prod = sum(rho[i][j] * sigma[j][i] for i in range(2) for j in range(2))
    det_rho = rho[0][0] * rho[1][1] - rho[0][1] * rho[1][0]
    det_sigma = sigma[0][0] * sigma[1][1] - sigma[0][1] * sigma[1][0]
    return tr_prod + 2 * math.sqrt(max(det_rho * det_sigma, 0.0))

"""Phase-register roundtrip pair - exact holdout API contract.

Graded entry points: phase_to_register_bits, register_bits_to_phase.
Quantization grid spacing 2**-n; roundtrip exact on the grid."""

from __future__ import annotations


def phase_to_register_bits(phase, n_qubits):
    if n_qubits <= 0:
        raise ValueError("n_qubits must be positive")
    if not (0.0 <= phase < 1.0):
        raise ValueError("phase must be in [0, 1)")
    scale = 1 << n_qubits
    integer_rep = int(phase * scale)
    bits = []
    for shift in range(n_qubits - 1, -1, -1):
        bits.append((integer_rep >> shift) & 1)
    return bits


def register_bits_to_phase(bits):
    if not bits:
        raise ValueError("bits list cannot be empty")
    if any(bit not in (0, 1) for bit in bits):
        raise ValueError("bits must be 0 or 1")
    integer_rep = 0
    for bit in bits:
        integer_rep = (integer_rep << 1) | bit
    scale = 1 << len(bits)
    return integer_rep / scale

